import type { Duration, TimeOfDay, Record, TimeZone } from '../db'

/** Utility type to create a range of numbers */
type Enumerate<N extends number, Acc extends number[] = []> = Acc['length'] extends N
    ? Acc[number]
    : Enumerate<N, [...Acc, Acc['length']]>

type Range<F extends number, T extends number> = Exclude<Enumerate<T>, Enumerate<F>> | F

/** Day of the week */
type DayOfWeek = 'monday' | 'tuesday' | 'wednesday' | 'thursday' | 'friday' | 'saturday' | 'sunday'

/** Day of the month (1-31) */
type DayOfMonth = Range<1, 32>

/** Week within the month (1-6) */
type WeekInMonth = Range<1, 7>

/** Month of the year (1-12) */
type MonthOfYear = Range<1, 13>

/**
 * Frequency at which the job runs.
 * - **daily**: Runs once per day at the specified time
 * - **day_and_month_in_year**: Runs on a specific day and month each year
 * - **weekly**: Runs on specific days of the week
 * - **monthly**: Runs on a specific day of the month
 * - **day_week_month_year**: Runs on a specific day in a specific week in a specific month each year
 * - **periodically**: Runs at regular intervals (defined by runPeriod)
 * - **once**: Runs once at the specified date/time
 * - **on_demand**: Only runs when manually triggered
 * - **week_in_month**: Runs on a specific week in the month
 * - **business_calendar_start**: Runs when a business calendar entry starts
 * - **business_calendar_end**: Runs when a business calendar entry ends
 */
type RunType =
    | 'daily'
    | 'day_and_month_in_year'
    | 'weekly'
    | 'monthly'
    | 'day_week_month_year'
    | 'periodically'
    | 'once'
    | 'on_demand'
    | 'week_in_month'
    | 'business_calendar_start'
    | 'business_calendar_end'

/** @interface */
export type ScheduledScript = Now.Internal.WithIdAndMetadata<{
    /** Name of the scheduled script execution job */
    name?: string

    /**
     * Script to be executed when the job runs.
     * Accepts a module function (imported from a server module), a `Now.include('./script.js')`
     * reference for file-based editing, or an inline string.
     */
    script?: ((...args: unknown[]) => void) | string

    /** Indicates whether the scheduled job is active and will run
     * @default true
     */
    active?: boolean

    /**
     * If true, the job only runs when the condition script evaluates to true.
     * Allows conditional execution of the job.
     * @default false
     */
    conditional?: boolean

    /**
     * Script-based condition that must evaluate to true for the job to run.
     * Only evaluated when conditional is true.
     */
    condition?: string

    /** Offset duration from the scheduled time */
    offset?: Duration

    /**
     * Direction of offset from the scheduled time.
     * - **future**: Job runs after the scheduled time
     * - **past**: Job runs before the scheduled time
     */
    offsetType?: 'future' | 'past'

    /** User whose credentials are used to execute the scheduled job (sys_id or username) */
    runAs?: string | Record<'sys_user'>

    /**
     * Time zone context for any GlideDateTime or relative date calculations inside the script.
     * Defaults to the time zone defined in the user profile of the user specified in the "Run as" field.
     */
    userTimeZone?: TimeZone

    /**
     * Frequency at which the job runs.
     */
    frequency?: RunType

    /** Specific day of the week when the job runs (for weekly jobs) */
    dayOfWeek?: DayOfWeek

    /** Days of the week when the job runs (array of day names) */
    daysOfWeek?: [DayOfWeek, ...DayOfWeek[]]

    /** Day of the month when the job runs (1-31) */
    dayOfMonth?: DayOfMonth

    /** Week within the month when the job runs (1=First, 2=Second, 3=Third, 4=Fourth, 5=Fifth, 6=Sixth) */
    weekInMonth?: WeekInMonth

    /** Month when the job runs (1-12, for yearly jobs) */
    month?: MonthOfYear

    /** Time of day when the job runs */
    executionTime?: TimeOfDay

    /** Interval between runs for periodic jobs */
    executionInterval?: Duration

    /** Date and time when the job should start running */
    executionStart?: string

    /** Date and time when the job should stop running. Jobs with ending values in the past are marked inactive */
    executionEnd?: string

    /** Maximum time the job can drift from its scheduled time before being cancelled */
    maxDrift?: Duration

    /** For recurring trigger types, repeat only every Nth occurrence (e.g., 3 means every 3rd occurrence) */
    repeatEvery?: number

    /** Indicates if this scheduled job should be preserved during upgrades
     * @default false
     */
    upgradeSafe?: boolean

    /** Time zone in which the job runs. Use 'floating' for system time zone
     * @default 'floating'
     */
    timeZone?: 'floating' | TimeZone

    /** Reference to a business calendar for calendar-based scheduling (sys_id of business_calendar) or new calendar record */
    businessCalendar?: string | Record<'business_calendar'>

    /** Indicates whether this job can run in advanced mode
     * @default false
     */
    advanced?: boolean
}> &
    Now.Internal.Meta

/**
 * Creates a Scheduled Script Execution: a server-side script that runs automatically
 * on a defined schedule (`sys_script_execution`).
 *
 * @param config - Configuration for the scheduled script
 * @see https://docs.servicenow.com/bundle/latest-platform-administration/page/administer/time/concept/scheduled-jobs.html
 */
export function ScheduledScript(config: ScheduledScript) {
    return config
}
